local function nativeDownloadHash(value)
 local crypto=crypt or (syn and syn.crypt)
 if crypto and type(crypto.hash)=="function" then
  local ok,digest=pcall(crypto.hash,value,"sha256")
  if ok and type(digest)=="string" and #digest==64 and string.match(digest,"^%x+$") then return string.lower(digest)end
 end
 return __vsh_sha256(value)
end

